<?php defined('ABSPATH')||exit; ?>
<?php  ?>
<div class="rdc-ctr rdc-main"><?php while(have_posts()):the_post(); ?><article <?php post_class(); ?>><?php get_template_part('shared/radmanct/template-parts/ui/content-heading'); ?><?php if(post_password_required()){echo get_the_password_form();}else{ ?>
<a href="<?php echo esc_url(get_post_type_archive_link('project')); ?>"><?php esc_html_e('Back to projects','radmanct'); ?></a>
<?php the_terms(get_the_ID(),'project_category','<div class="rdc-tags">',' ','</div>');if(has_excerpt())the_excerpt();the_post_thumbnail('full',array('class'=>'rdc-prj-cvr','fetchpriority'=>'high','loading'=>'eager','sizes'=>'100vw')); ?>
<?php $project=get_post_meta(get_the_ID(),'_webtalik_project',true);if(is_array($project)): ?>
<?php if(!empty($project['gallery'])&&is_array($project['gallery'])): ?><div class="rdc-prj-gal"><?php foreach(array_unique(array_map('absint',$project['gallery']))as$media_id){if(!wp_attachment_is_image($media_id)||get_post_status($media_id)==='private')continue;$attachment=get_post($media_id);$parent=$attachment?get_post($attachment->post_parent):null;if($parent&&(!in_array($parent->post_status,array('publish','inherit'),true)||post_password_required($parent)))continue;echo '<a href="'.esc_url(wp_get_attachment_url($media_id)).'" data-rdc-gal>'.wp_get_attachment_image($media_id,'large',false,array('loading'=>'lazy','sizes'=>'(max-width:768px) 100vw,50vw')).'</a>';} ?></div><?php endif; ?>
<?php if(!empty($project['specifications'])): ?><dl class="rdc-prj-meta"><?php foreach($project['specifications']as$spec){if(!is_array($spec)||!is_scalar($spec['label']??null)||!is_scalar($spec['value']??null))continue;echo '<div><dt>'.esc_html($spec['label']).'</dt><dd>'.esc_html($spec['value']).'</dd></div>';} ?></dl><?php endif;endif; ?>
<div class="rdc-cnt"><?php the_content();wp_link_pages(); ?></div>
<?php $meta=get_post_meta(get_the_ID(),'_webtalik_project',true);if(is_array($meta)&&$meta){echo '<dl class="rdc-prj-meta">';foreach(array('client'=>__('Client','radmanct'),'date'=>__('Date','radmanct'),'year'=>__('Year','radmanct'),'website'=>__('Website','radmanct'),'url'=>__('Website','radmanct'))as$key=>$label){if(empty($meta[$key])||!is_scalar($meta[$key]))continue;echo '<div><dt>'.esc_html($label).'</dt><dd>';if(in_array($key,array('url','website'),true)&&preg_match('~^https?://~i',$meta[$key]))echo '<a href="'.esc_url($meta[$key]).'" rel="noopener noreferrer">'.esc_html($meta[$key]).'</a>';else echo esc_html($meta[$key]);echo '</dd></div>';}echo '</dl>';} ?>
<?php } ?></article><?php endwhile; ?></div><?php get_template_part('shared/radmanct/template-parts/layout/continuation'); ?><?php  ?>
